import os
import pandas as pd
import streamlit as st
import streamlit.components.v1 as components

st.set_page_config(page_title="SmartBuy", layout="wide")

# Load latest live prices and signals generated by analysis.py
signals_path = "output/buy_wait_signals.csv"
if os.path.exists(signals_path):
    df_signals = pd.read_csv(signals_path)
    buy_count = len(df_signals[df_signals['Signal'] == 'BUY_NOW'])
    wait_count = len(df_signals[df_signals['Signal'] == 'WAIT'])
    dont_buy_count = len(df_signals[df_signals['Signal'] == 'DON_T_BUY'])
    total_count = len(df_signals)
else:
    total_count, buy_count, wait_count, dont_buy_count = 77, 8, 67, 2

# Read index.html template and inject live dynamic metrics
if os.path.exists("index.html"):
    with open("index.html", "r", encoding="utf-8") as f:
        html_content = f.read()
    
    # Replace static metrics with live CSV counts
    html_content = html_content.replace('id="tracked-count">77', f'id="tracked-count">{total_count}')
    html_content = html_content.replace('id="buy-count">8', f'id="buy-count">{buy_count}')
    
    components.html(html_content, height=1200, scrolling=True)